\begin{enumerate}
\item $U$ is an open subscheme of $X$,
\item $V$ is an open subscheme of $Y$, and
\item there exists an isomorphism $A = V \times \Spec(P)$ over $V$
where $P$ is a polynomial algebra over $\mathbf{Z}$ (on some set
of variables).
\end{enumerate}
